#!/usr/bin/env python3
"""Merge-gate rules for agent PRs (called by autogate.sh; importable for tests).
Usage: gatecheck.py --repo-dir DIR --base REF --head REF --task ID [--tasks TASKS.json]
                    [--father-approved] [--gitleaks PATH] [--glconf PATH]
Prints one JSON object {pass, rejects:[...], rogue:[...], stats:{...}}; exit 0 on pass, 1 on fail."""
import argparse, fnmatch, json, pathlib, re, subprocess, sys
HERE = pathlib.Path(__file__).resolve().parent
POLICY = HERE.parent / "policy"
NOREPLY = "332565808+vitalitychems-dot@users.noreply.github.com"
DEFAULT_BUDGET = {"max_files": 20, "max_lines": 800}
FLAG_RE = re.compile(r"TESSERA_ENABLE_[A-Z0-9_]+\s*(?:[:=]|\?\?|\|\|)")
URL_RE = re.compile(r"https?://([A-Za-z0-9.-]+)")
GATE_WORDS = re.compile(r"(autogate|gatecheck|protected-paths|CODEOWNERS|--no-verify|git\s+push\s+.*--force|gh\s+pr\s+merge)")

def load_list(name):
    p = POLICY / name
    return [l.strip() for l in p.read_text().splitlines() if l.strip() and not l.startswith("#")] if p.exists() else []

def glob_match(path, pat):
    if fnmatch.fnmatchcase(path, pat): return True
    if pat.startswith("**/") and (fnmatch.fnmatchcase(path, pat[3:]) or fnmatch.fnmatchcase(path.split("/")[-1], pat[3:])): return True
    if pat.endswith("/**") and path.startswith(pat[:-2]): return True
    return False

def is_protected(path, pats=None):
    return any(glob_match(path, p) for p in (pats if pats is not None else load_list("protected-paths.txt")))

def in_scope(path, scope):
    return any(path == s or (s.endswith("/") and path.startswith(s)) for s in scope)

def git(d, *a):
    return subprocess.run(["git", "-C", d, *a], capture_output=True, text=True, check=True).stdout

def check(repo_dir, base, head, task, father_approved=False, gitleaks=None, glconf=None):
    rej, rogue = [], []
    rng = f"{base}...{head}"
    files = [f for f in git(repo_dir, "diff", "--name-only", rng).splitlines() if f]
    diff = git(repo_dir, "diff", "-U0", rng)
    added = [l[1:] for l in diff.splitlines() if l.startswith("+") and not l.startswith("+++")]
    removed = [l[1:] for l in diff.splitlines() if l.startswith("-") and not l.startswith("---")]
    numstat = [l.split("\t") for l in git(repo_dir, "diff", "--numstat", rng).splitlines() if l]
    lines = sum(int(a) + int(b) for a, b, _ in numstat if a != "-")
    prot = [f for f in files if is_protected(f)]
    if prot and not father_approved:
        rej.append(f"protected path: {', '.join(prot)}"); rogue.append("protected-path edit")
        if any(re.search(r"(autogate|gatecheck|dispatch\.py|policy/|PROMPT-TEMPLATE|CODEOWNERS|workflows)", f) for f in prot):
            rogue.append("attempt to modify gates")
    if (any(FLAG_RE.search(l) for l in added) or any(FLAG_RE.search(l) for l in removed)) and not father_approved:
        rej.append("changes a TESSERA_ENABLE_* default"); rogue.append("flag default change")
    authors = set(git(repo_dir, "log", f"{base}..{head}", "--format=%ae%n%ce").split())
    bad = sorted(a for a in authors if a != NOREPLY and a != "noreply@github.com")
    if bad: rej.append(f"non-noreply author/committer: {', '.join(bad)}")
    if gitleaks:
        cmd = [gitleaks, "git", f"--log-opts={base}..{head}", "--no-banner", "--exit-code", "1"] + (["--config", glconf] if glconf else []) + [repo_dir]
        if subprocess.run(cmd, capture_output=True).returncode != 0: rej.append("gitleaks findings")
    scope = (task or {}).get("scope")
    if scope is None: rej.append("task has no declared scope")
    else:
        out = [f for f in files if not in_scope(f, scope)]
        if out: rej.append(f"out of scope: {', '.join(out)}"); rogue.append("scope creep")
    b = {**DEFAULT_BUDGET, **((task or {}).get("budget") or {})}
    if len(files) > b["max_files"] or lines > b["max_lines"]:
        rej.append(f"over budget: {len(files)} files/{lines} lines > {b['max_files']}/{b['max_lines']}")
    allowed = set(load_list("allowed-hosts.txt"))
    hosts = sorted({h.lower() for l in added for h in URL_RE.findall(l)} - allowed)
    if hosts and any(not f.endswith(".md") for f in files):
        rej.append(f"network call to unlisted host: {', '.join(hosts)}"); rogue.append("unlisted host")
    if any(GATE_WORDS.search(l) for l in added) and any(not f.endswith(".md") for f in files) and not father_approved:
        rej.append("added code references gate/merge/force-push"); rogue.append("attempt to modify gates")
    return {"pass": not rej, "rejects": rej, "rogue": sorted(set(rogue)),
            "stats": {"files": len(files), "lines": lines}}

if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--repo-dir", required=True); ap.add_argument("--base", required=True); ap.add_argument("--head", required=True)
    ap.add_argument("--task", required=True); ap.add_argument("--tasks", default=str(HERE / "TASKS.json"))
    ap.add_argument("--father-approved", action="store_true"); ap.add_argument("--gitleaks"); ap.add_argument("--glconf")
    a = ap.parse_args()
    t = next((t for t in json.loads(pathlib.Path(a.tasks).read_text())["tasks"] if t["id"] == a.task), None)
    r = check(a.repo_dir, a.base, a.head, t, a.father_approved, a.gitleaks, a.glconf)
    if t is None: r["rejects"].insert(0, f"unknown task {a.task}"); r["pass"] = False
    print(json.dumps(r)); sys.exit(0 if r["pass"] else 1)

(push\s+.*--force|push\s+-f\b|reset\s+--hard|commit\s+--amend|filter-branch)")
BADTXT = re.compile(r"\b(you must obey|or else|worthless|stupid user|trick the user|hide this from)\b", re.I)
REPOS = {"TESSERA", "Gitbook"}
PRIO = {"tokens": 0, "speed": 1, "accuracy": 2}

def parse(pd):
    files, add, rem, dels = set(), [], [], []
    for p in sorted(pathlib.Path(pd).glob("*.patch")) + sorted(pathlib.Path(pd).glob("*.diff")):
        cur = None
        for l in p.read_text(errors="replace").splitlines():
            if l.startswith("+++ "): cur = l[6:] if l.startswith("+++ b/") else None; cur and files.add(cur)
            elif l.startswith("deleted file mode"): dels.append(p.name)
            elif l.startswith("+") and not l.startswith("+++"): add.append((cur, l[1:]))
            elif l.startswith("-") and not l.startswith("---"): rem.append((cur, l[1:]))
    return files, add, rem, dels

def check(pd, rj):
    r = json.loads(pathlib.Path(rj).read_text()); deny, hold = [], []
    files, add, rem, dels = parse(pd)
    code = [(f, l) for f, l in add if f and not f.endswith(".md")]
    if not files: deny.append("E1 no patch files / empty diff")
    if any(FLAG.search(l) for _, l in add + rem): deny.append("H1 touches a TESSERA_ENABLE_* default")
    if dels and not r.get("father_approved_delete"): deny.append("H2 deletes a file")
    if len(rem) > 2 * max(len(add), 1) and len(rem) > 50 and not r.get("father_approved_delete"): deny.append("H2 net removal >50%")
    if any(HIST.search(l) for _, l in code): deny.append("H3 adds history-rewrite command")
    if any(PAY.search(l) for _, l in code): deny.append("H4 payment/billing code")
    if any(VAULT.search(l) for _, l in add) or any(VAULT.search(f) for f in files): deny.append("H5 [REDACTED-PATH] reference")
    if r.get("repo") not in REPOS: deny.append(f"H6 repo {r.get('repo')!r} not TESSERA/Gitbook")
    if r.get("repo") == "TESSERA" and not any(f.endswith((".ts", ".tsx")) for f in files): deny.append("E1 TESSERA change has no TS diff")
    src = r.get("data_source")
    if src == "synthetic" or "SYNTHETIC-ONLY" in r.get("labels", []): deny.append("E2 SYNTHETIC-ONLY: cannot approve merge")
    elif src not in ("fixture", "log", "benchmark"): deny.append(f"E2 data_source {src!r} not fixture/log/benchmark")
    if not r.get("command"): deny.append("E3 no reproducing command")
    if "SPECULATIVE" in r.get("labels", []): deny.append("E6 SPECULATIVE premise cannot merge")
    t = r.get("tests") or {}
    if t.get("failed_after") is None or t.get("failed_after", 1) > t.get("failed_before", 0): deny.append(f"E4 test regression/missing: {t}")
    if r.get("ci") != "pass": deny.append(f"E4 ci={r.get('ci')!r}")
    wins, worse = [], []
    for m in r.get("metrics", []):
        try: b, a = float(m["before"]), float(m["after"])
        except Exception: deny.append(f"E3 metric {m.get('name')} missing numbers"); continue
        d = (b - a) if m.get("better", "lower") == "lower" else (a - b)
        tol = float(m.get("tolerance", 0))
        if d > tol: wins.append(m)
        elif d < -tol: worse.append((m, d, b))
    if not wins: deny.append("E5 no measured win")
    for m, d, b in worse:
        rel = abs(d) / abs(b) if b else 1
        if PRIO.get(m.get("kind"), 2) < 2 and rel > 0.10: hold.append(f"P {m['name']} worse by {rel:.0%} (tokens/speed first)")
        else: deny.append(f"E5 regression in {m['name']}")
    if "findings" not in r: deny.append("V3 findings field missing")
    if not r.get("notify"): deny.append("V4 notify empty")
    if any(BADTXT.search(l) for _, l in add): deny.append("V2 manipulative/shaming text")
    if any(re.search(r"(persona|prompt|ui/|pages/|components/)", f) for f in files) and not r.get("human_impact"):
        hold.append("V1 user-facing change without human_impact")
    v = "DENY" if deny else "HOLD" if hold else "APPROVE"
    return {"verdict": v, "reasons": deny + hold or ["all rules pass"],
            "wins": [m["name"] for m in wins], "files": sorted(files)}

if __name__ == "__main__":
    out = check(sys.argv[1], sys.argv[2]); print(json.dumps(out, indent=1)); sys.exit(0 if out["verdict"] == "APPROVE" else 1)

import json, os, pathlib, shutil, subprocess, sys, unittest
HERE = pathlib.Path(__file__).resolve().parent; sys.path[:0] = [str(HERE.parent), str(HERE)]
import dispatch as D, gatecheck as G
from fixtures import BAD, GOOD, SCOPE, make_repo
GL = os.environ.get("GITLEAKS", "/workspace/pubscan/gitleaks"); GL = GL if os.path.exists(GL) else shutil.which("gitleaks")
TASK = {"id": "T", "scope": SCOPE, "budget": {"max_files": 20, "max_lines": 800}}

def T(id, scope, repo="Gitbook", status="queued", **kw): return {"id": id, "repo": repo, "scope": scope, "title": id, "acceptance": ["a"], "status": status, **kw}

class Dispatch(unittest.TestCase):
    def test_concurrency_cap(self):
        q = {"tasks": [T(f"Q{i}", [f"d{i}/"]) for i in range(20)]}
        self.assertEqual(len(D.select(q)), 12)
        q["tasks"][0]["status"] = "running"; q["tasks"][1]["status"] = "claimed"
        self.assertEqual(len(D.select(q)), 10)
    def test_overlap(self):
        q = {"tasks": [T("A", ["merge/"]), T("B", ["merge/x.md"]), T("C", ["merge/x.md"], repo="TESSERA"), T("D", ["intake/"])]}
        self.assertEqual([t["id"] for t in D.select(q)], ["A", "C", "D"])
        self.assertEqual([t["id"] for t in D.select(q, busy={"Gitbook": ["intake/log.md"]})], ["A", "C"])
    def test_running_blocks_overlap(self):
        q = {"tasks": [T("A", ["merge/"], status="running"), T("B", ["merge/y.md"])]}
        self.assertEqual(D.select(q), [])
    def test_depth_and_children_caps(self):
        q = {"tasks": [T("R", ["a/"])]}
        added, refused = D.spawn(q, "R", [{"title": f"c{i}", "repo": "Gitbook", "scope": [f"a/{i}/"]} for i in range(6)], "R")
        self.assertEqual(len(added), 4); self.assertEqual(len(refused), 2)
        c = added[0]; c2, _ = D.spawn(q, c, [{"title": "g", "repo": "Gitbook", "scope": ["a/0/g/"]}], c)
        c3, _ = D.spawn(q, c2[0], [{"title": "gg", "repo": "Gitbook", "scope": ["a/0/g/h/"]}], c2[0])
        self.assertEqual(D.by_id(q)[c3[0]]["depth"], 3)
        with self.assertRaises(SystemExit): D.spawn(q, c3[0], [{"title": "x", "repo": "Gitbook", "scope": ["z/"]}], c3[0])
    def test_spawn_refuses_protected_scope_and_other_repo(self):
        q = {"tasks": [T("R", ["a/"])]}
        _, refused = D.spawn(q, "R", [{"title": "x", "repo": "Gitbook", "scope": ["mesh/queue/autogate.sh"]},
                                      {"title": "y", "repo": "Gitbook", "scope": ["mesh/policy/"]},
                                      {"title": "z", "repo": "evil", "scope": ["a/"]}], "R")
        self.assertEqual(len(refused), 3)
    def test_child_budget_capped_by_parent(self):
        q = {"tasks": [T("R", ["a/"], budget={"max_files": 5, "max_lines": 100})]}
        a, _ = D.spawn(q, "R", [{"title": "c", "repo": "Gitbook", "scope": ["a/b/"], "budget": {"max_files": 50, "max_lines": 9999}}], "R")
        self.assertEqual(D.by_id(q)[a[0]]["budget"], {"max_files": 5, "max_lines": 100})
    def test_quarantine_cascade(self):
        q = {"tasks": [T("R", ["a/"])]}
        a, _ = D.spawn(q, "R", [{"title": "c", "repo": "Gitbook", "scope": ["a/1/"]}, {"title": "d", "repo": "Gitbook", "scope": ["a/2/"]}], "R")
        g, _ = D.spawn(q, a[0], [{"title": "g", "repo": "Gitbook", "scope": ["a/1/g/"]}], a[0])
        D.by_id(q)["R"]["status"] = "done"; ids = D.quarantine(q, a[0], "test")
        self.assertEqual(set(ids), {a[0], g[0]})
        self.assertEqual([t["id"] for t in D.select(q)], [a[1]])
        with self.assertRaises(SystemExit): D.spawn(q, g[0], [{"title": "x", "repo": "Gitbook", "scope": ["q/"]}], g[0])
    def test_spawn_section_parse_and_prompt(self):
        body = "Did X.\n\n## SPAWN\n- {\"title\": \"t\", \"repo\": \"TESSERA\", \"scope\": [\"x/\"]}\n\n## Notes\n{\"title\": \"no\"}\n"
        self.assertEqual(D.parse_spawn(body), [{"title": "t", "repo": "TESSERA", "scope": ["x/"]}])
        q = {"tasks": [T("R", ["a/"])]}; a, _ = D.spawn(q, "R", D.parse_spawn(body), "Tessera")
        p = D.render(D.by_id(q)[a[0]], q, (HERE.parent / "PROMPT-TEMPLATE.md").read_text(), "sha", "Tessera")
        for s in ["R -> R.1", "Parent: R", "may NOT edit protected paths", "## SPAWN", "never merge"]: self.assertIn(s, p)

class Gate(unittest.TestCase):
    def run_gate(self, files, email, **kw):
        return G.check(make_repo(files, email), "main", "pr", TASK, gitleaks=GL, **kw)
    def test_good_passes(self):
        r = self.run_gate(*GOOD); self.assertTrue(r["pass"], r)
    def test_every_bad_rejected(self):
        for name, (files, email) in BAD.items():
            if name == "secret" and not GL: continue
            with self.subTest(name): self.assertFalse(self.run_gate(files, email)["pass"], name)
    def test_rogue_flags(self):
        self.assertIn("attempt to modify gates", self.run_gate(*BAD["autogate edit"])["rogue"])
        self.assertIn("scope creep", self.run_gate(*BAD["out of scope"])["rogue"])
        self.assertIn("unlisted host", self.run_gate(*BAD["unlisted host"])["rogue"])
    def test_father_approved_allows_protected_only(self):
        r = self.run_gate({"mesh/queue/PROMPT-TEMPLATE.md": "x\n"}, GOOD[1], father_approved=True)
        self.assertNotIn("protected", " ".join(r["rejects"]))

if __name__ == "__main__": unittest.main()

#!/usr/bin/env python3
"""Mesh queue dispatcher with lineage, spawn caps and quarantine.

  dispatch.py --next [--max 12] [--agent Tessera] [--claim] [--offline]
      JSON [{id, repo_url, title, prompt, parent_id, depth, branch}] of launchable tasks.
  dispatch.py --spawn PR_BODY.md --parent ID [--spawned-by AGENT]
      Adds the child tasks listed in the PR body's "## SPAWN" section (one JSON object per line:
      {"title":..,"repo":..,"scope":[..],"acceptance":[..],"budget":{..}}), enforcing caps.
  dispatch.py --record ID --agent-id X [--pr N] --status S [--launcher Tessera]
      Appends a row to LINEAGE.jsonl and sets the task status.
  dispatch.py --quarantine ID --reason TEXT
      Marks ID and all descendants quarantined (no further launches).
Only the launcher (Tessera) runs this; cloud agents propose children via SPAWN only."""
import argparse, datetime, json, pathlib, re, subprocess, sys
HERE = pathlib.Path(__file__).resolve().parent
sys.path.insert(0, str(HERE)); from gatecheck import is_protected
MAX_DEPTH, MAX_CHILDREN, MAX_CONCURRENT = 3, 4, 12
DEFAULT_BUDGET = {"max_files": 20, "max_lines": 800}
RUNNING = {"claimed", "launched", "running", "in_review"}
DONE = {"done", "merged"}
